#!/usr/bin/env node
/**
 * Regenerate the checked-in ModelPulseX free catalog + performance snapshot.
 *
 *   node scripts/sync-modelpulse.mjs
 *
 * Sources:
 *   GET /api/models?includeInactive=1       → free/previously-free catalog
 *   GET /api/leaderboard?range=24h&...      → measured TPS/TTFT/uptime
 *
 * The generated file is the router's offline fallback when ModelPulseX is
 * unreachable or stale. It never overwrites on a failed fetch.
 */

import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const outPath = join(root, 'src/mpx-catalog.generated.ts');
const BASE = (process.env.MODELPULSE_URL || 'https://modelpulsex.pages.dev').replace(/\/+$/, '');

const PROVIDER_MAP = {
  opencode_zen: 'zen',
  opencode_go: 'opencode',
  ollama_pro: 'ollama',
  tokenrouter: 'truerouter',
};

function normalizeProvider(name) {
  const raw = typeof name === 'string' ? name.trim() : '';
  return PROVIDER_MAP[raw] ?? raw;
}

function normalizeModelId(id) {
  return typeof id === 'string' ? id.trim().replace(/^models\//, '') : '';
}

function asString(v) {
  return typeof v === 'string' ? v.trim() : '';
}

function asNumber(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  if (typeof v === 'string' && v.trim() !== '') {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

function asCount(v) {
  const n = asNumber(v);
  return n == null || n < 0 ? 0 : Math.floor(n);
}

function asFreeStatus(v) {
  const s = asString(v).toUpperCase();
  if (s === 'FREE') return 'FREE';
  if (s === 'PREVIOUSLY_FREE') return 'PREVIOUSLY_FREE';
  return 'UNKNOWN';
}

function asCapabilities(v) {
  if (Array.isArray(v)) return v.filter((c) => typeof c === 'string');
  if (typeof v === 'string') {
    try {
      const parsed = JSON.parse(v);
      return Array.isArray(parsed) ? parsed.filter((c) => typeof c === 'string') : [];
    } catch {
      return [];
    }
  }
  return [];
}

async function getJson(path) {
  const res = await fetch(`${BASE}${path}`, {
    headers: { accept: 'application/json' },
    signal: AbortSignal.timeout(15_000),
  });
  if (!res.ok) throw new Error(`GET ${path} → ${res.status}`);
  return res.json();
}

function buildCatalog(payload) {
  const list = Array.isArray(payload?.models) ? payload.models : [];
  const out = [];
  const seen = new Set();
  for (const raw of list) {
    if (!raw || typeof raw !== 'object') continue;
    const provider = normalizeProvider(asString(raw.provider_name));
    const id = normalizeModelId(asString(raw.provider_model_id));
    if (!provider || !id) continue;
    const key = `${provider}:${id}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({
      provider,
      id,
      freeStatus: asFreeStatus(raw.free_status),
      active: raw.active === true || raw.active === 1,
      context: asCount(raw.context_length) || 131_072,
      capabilities: asCapabilities(raw.capabilities),
    });
  }
  return out;
}

function buildPerf(payload) {
  const list = Array.isArray(payload?.leaderboard) ? payload.leaderboard : [];
  const out = [];
  const seen = new Set();
  for (const raw of list) {
    if (!raw || typeof raw !== 'object') continue;
    const provider = normalizeProvider(asString(raw.provider));
    const model = normalizeModelId(asString(raw.model));
    if (!provider || !model) continue;
    const key = `${provider}:${model}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({
      provider,
      model,
      freeStatus: asFreeStatus(raw.free_status),
      active: raw.active !== false,
      status: asString(raw.status).toUpperCase() || 'UNKNOWN',
      tps24: asNumber(raw.tps_24h ?? raw.tps_1h ?? raw.tps_now),
      ttft24: asNumber(raw.ttft_24h ?? raw.ttft_1h ?? raw.ttft_now),
      uptime7d: asNumber(raw.uptime_7d ?? raw.uptime_24h),
      samples24h: asCount(raw.sampleCount24h ?? raw.samples24h),
    });
  }
  return out;
}

async function main() {
  const [models, leaderboard] = await Promise.all([getJson('/api/models?includeInactive=1'), getJson('/api/leaderboard?range=24h&sort=overall&profile=balanced')]);
  const catalog = buildCatalog(models);
  const perf = buildPerf(leaderboard);
  if (catalog.length === 0) throw new Error('ModelPulseX returned an empty catalog — refusing to overwrite');
  if (perf.length === 0) throw new Error('ModelPulseX returned an empty leaderboard — refusing to overwrite');

  const body = `// AUTO-GENERATED by scripts/sync-modelpulse.mjs — do not edit.
// Source: ${BASE}
import type { MpxCatalogModel, MpxPerfRow } from './mpx';

export const MPX_SNAPSHOT_AT = ${JSON.stringify(new Date().toISOString())};

export const MPX_CATALOG: MpxCatalogModel[] = ${JSON.stringify(catalog, null, 2)};

export const MPX_PERF: MpxPerfRow[] = ${JSON.stringify(perf, null, 2)};
`;

  writeFileSync(outPath, body);
  const free = catalog.filter((m) => m.freeStatus === 'FREE' && m.active).length;
  console.log(`wrote ${outPath}: ${catalog.length} catalog rows (${free} free), ${perf.length} perf rows`);
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});
